read_examples <- function(path) {
    lines <- strsplit(readLines(path), ",", fixed = TRUE)
    names <- lines[[1L]][-c(1L, length(lines[[1L]]))]
    rows <- lapply(
        lines[-1L],
        function(fields) list(
            id = fields[1L],
            values = as.numeric(fields[-c(1L, length(fields))]),
            label = as.integer(tail(fields, 1L))
        )
    )
    list(names = names, rows = rows)
}
read_inputs <- function() {
    train <- read_examples("input/train.csv")
    test <- read_examples("input/test.csv")
    entries <- list()
    for (fields in strsplit(
        readLines("input/params.txt"),
        " ",
        fixed = TRUE
    )) entries[[fields[1L]]] <- fields[-1L]
    integer <- function(key, i = 1L) as.integer(entries[[key]][i])
    real <- function(key, i = 1L) as.numeric(entries[[key]][i])
    settings <- list(positive = integer("POSITIVE"), degree = integer("DEGREE"), threshold = real("THRESHOLD"), lambdas = as.numeric(entries$LAMBDAS),
        gd_rate = real("GD"), gd_iterations = integer("GD", 2L), sgd_rate = real("SGD"), batch_size = integer("SGD", 2L), epochs = integer(
            "SGD",
            3L
        ), sgd_seed = integer(
            "SGD",
            4L
        ),
        softmax_rate = real("SOFTMAX"), softmax_iterations = integer("SOFTMAX", 2L), softmax_lambda = real(
            "SOFTMAX",
            3L
        ), bootstrap_count = integer("BOOTSTRAP"), bootstrap_seed = integer(
            "BOOTSTRAP",
            2L
        ),
        permutation_count = integer("PERMUTATION"), permutation_seed = integer(
            "PERMUTATION",
            2L
        ), map_width = integer("MAP"), map_height = integer("MAP", 2L), cost_fp = integer("COST"), cost_fn = integer(
            "COST",
            2L
        ))
    list(names = train$names, train = train$rows, test = test$rows, settings = settings)
}
expansion_tuples <- function(base_count, degree) {
    tuples <- list()
    append_tuples <- function(prefix, remaining, first) {
        if (remaining == 0L) tuples[[length(tuples) + 1L]] <<- prefix else for (index in seq.int(
            first,
            base_count
        )) append_tuples(
            c(prefix, index),
            remaining - 1L,
            index
        )
    }
    for (k in seq_len(degree)) append_tuples(integer(), k, 1L)
    tuples
}
expanded_names <- function(names, tuples) vapply(
    tuples,
    function(indices) paste(names[indices], collapse = "*"),
    ""
)
expanded_values <- function(tuples, values) vapply(tuples, function(indices) {
    product <- values[indices[1L]]
    for (index in indices[-1L]) product <- product * values[index]
    product
}, 0)
compute_statistics <- function(rows, count) {
    means <- deviations <- numeric(count)
    for (j in seq_len(count)) {
        total <- 0
        for (row in rows) total <- total + row[j]
        mean <- total / length(rows)
        squares <- 0
        for (row in rows) squares <- squares + (row[j] - mean) * (row[j] - mean)
        means[j] <- mean
        deviations[j] <- sqrt(squares / (length(rows) - 1L))
    }
    list(means = means, deviations = deviations)
}
standardize <- function(values, statistics, count) c(
    1,
    (values[seq_len(count)] - statistics$means[seq_len(count)]) / statistics$deviations[seq_len(count)]
)

ordered_sum <- function(values) {
    total <- 0
    for (value in values) total <- total + value
    total
}
score <- function(weights, vector) ordered_sum(weights * vector)
probability <- function(u) {
    if (u >= 0) return(1 / (1 + exp(-u)))
    e <- exp(u)
    e / (1 + e)
}
logistic_loss <- function(u, y) max(u, 0) - y * u + log(1 + exp(-abs(u)))
average_loss <- function(w, x, y) ordered_sum(vapply(
    seq_along(x),
    function(i) logistic_loss(score(w, x[[i]]), y[i]),
    0
)) / length(x)
penalty <- function(w) ordered_sum(w[-1L] * w[-1L])
objective <- function(w, x, y, lambda) average_loss(w, x, y) + lambda * penalty(w) / 2
gradient <- function(w, x, y, lambda) {
    totals <- numeric(length(w))
    for (i in seq_along(x)) {
        error <- probability(score(w, x[[i]])) - y[i]
        for (j in seq_along(w)) totals[j] <- totals[j] + error * x[[i]][j]
    }
    totals / length(x) + c(0, lambda * w[-1L])
}
hessian <- function(w, x, lambda) {
    size <- length(w)
    totals <- matrix(0, size, size)
    for (v in x) {
        pi <- probability(score(w, v))
        variance <- pi * (1 - pi)
        for (j in seq_len(size)) for (k in seq_len(j)) totals[j, k] <- totals[j, k] + variance * v[j] * v[k]
    }
    result <- matrix(0, size, size)
    for (j in seq_len(size)) for (k in seq_len(j)) {
        value <- totals[j, k] / length(x)
        if (j == k && j >= 2L) value <- value + lambda
        result[j, k] <- result[k, j] <- value
    }
    result
}

fixed <- function(value, places = 4L) {
    text <- sprintf(paste0("%.", places, "f"), value)
    if (startsWith(text, "-") && as.numeric(text) == 0) substring(text, 2L) else text
}
ratio <- function(a, b) {
    if (b == 0L) return("-")
    q <- (20000 * a + b) %/% (2 * b)
    paste0(sprintf("%.0f", q %/% 10000), ".", sprintf("%04d", as.integer(q %% 10000)))
}
gcd <- function(a, b) {
    while (b != 0L) {
        remainder <- a %% b
        a <- b
        b <- remainder
    }
    a
}
fraction <- function(a, b = NULL) {
    if (is.null(b)) {
        b <- a[2L]
        a <- a[1L]
    }
    divisor <- gcd(a, b)
    paste0(a %/% divisor, "/", b %/% divisor, " ", ratio(a, b))
}
confusion <- function(predictions, targets) list(
    tp = sum(predictions == 1L & targets == 1L),
    fp = sum(predictions == 1L & targets == 0L),
    tn = sum(predictions == 0L & targets == 0L),
    fn = sum(predictions == 0L & targets == 1L)
)
auc <- function(scores, targets) {
    order <- order(scores, seq_along(scores))
    positives <- sum(targets)
    rank_sum <- 0L
    start <- 1L
    while (start <= length(order)) {
        end <- start
        while (end < length(order) && scores[order[end + 1L]] == scores[order[start]]) end <- end + 1L
        for (position in seq.int(
            start,
            end
        )) if (targets[order[position]] == 1L) rank_sum <- rank_sum + start + end
        start <- end + 1L
    }
    c(rank_sum - positives * (positives + 1L), 2L * positives * (length(targets) - positives))
}
roc_points <- function(probabilities, targets) {
    order <- order(-probabilities, seq_along(probabilities))
    points <- list()
    tp <- fp <- 0L
    for (position in seq_along(order)) {
        i <- order[position]
        if (targets[i] == 1L) tp <- tp + 1L else fp <- fp + 1L
        if (position == length(order) || probabilities[order[position + 1L]] != probabilities[i]) points <- c(
            points,
            list(list(threshold = probabilities[i], tp = tp, fp = fp))
        )
    }
    points
}

minstd <- function(seed) {
    rng <- new.env(parent = emptyenv())
    rng$state <- seed
    rng
}
draw <- function(rng) {
    value <- 48271L * (rng$state %% 44488L) - 3399L * (rng$state %/% 44488L)
    if (value <= 0L) value <- value + 2147483647L
    rng$state <- value
    value
}
shuffle_order <- function(order, rng) {
    if (length(order) > 1L) for (i in seq.int(length(order), 2L)) {
        k <- draw(rng) %% i + 1L
        order[c(i, k)] <- order[c(k, i)]
    }
    order
}
gradient_descent <- function(x, y, lambda, rate, iterations) {
    w <- numeric(length(x[[1L]]))
    checkpoints <- list(list(iteration = 0L, weights = w))
    for (t in seq_len(iterations)) {
        w <- w - rate * gradient(w, x, y, lambda)
        if (t %% 100L == 0L) checkpoints <- c(checkpoints, list(list(iteration = t, weights = w)))
    }
    checkpoints
}
stochastic_gradient_descent <- function(x, y, lambda, rate, batch_size, epochs, seed) {
    rng <- minstd(seed)
    order <- seq_along(x)
    w <- numeric(length(x[[1L]]))
    checkpoints <- list(list(iteration = 0L, weights = w))
    for (epoch in seq_len(epochs)) {
        order <- shuffle_order(order, rng)
        for (start in seq.int(1L, length(order), batch_size)) {
            batch <- order[seq.int(start, min(start + batch_size - 1L, length(order)))]
            w <- w - rate * gradient(w, x[batch], y[batch], lambda)
        }
        checkpoints <- c(checkpoints, list(list(iteration = epoch, weights = w)))
    }
    checkpoints
}
cholesky_lower <- function(matrix) {
    count <- nrow(matrix)
    lower <- matrix(0, count, count)
    for (j in seq_len(count)) for (i in seq.int(j, count)) {
        total <- 0
        for (k in seq_len(j - 1L)) total <- total + lower[i, k] * lower[j, k]
        remainder <- matrix[i, j] - total
        lower[i, j] <- if (i == j) sqrt(remainder) else remainder / lower[j, j]
    }
    lower
}
solve_lower <- function(lower, values) {
    count <- length(values)
    middle <- solution <- numeric(count)
    for (i in seq_len(count)) {
        total <- 0
        for (k in seq_len(i - 1L)) total <- total + lower[i, k] * middle[k]
        middle[i] <- (values[i] - total) / lower[i, i]
    }
    for (i in rev(seq_len(count))) {
        total <- 0
        if (i < count) for (k in seq.int(i + 1L, count)) total <- total + lower[k, i] * solution[k]
        solution[i] <- (middle[i] - total) / lower[i, i]
    }
    solution
}
newton_direction <- function(w, x, y, lambda) {
    g <- gradient(w, x, y, lambda)
    list(gradient = g, step = solve_lower(cholesky_lower(hessian(w, x, lambda)), g))
}
newton_method <- function(x, y, lambda) {
    w <- numeric(length(x[[1L]]))
    checkpoints <- list(list(iteration = 0L, weights = w))
    for (t in seq_len(10L)) {
        w <- w - newton_direction(w, x, y, lambda)$step
        checkpoints <- c(checkpoints, list(list(iteration = t, weights = w)))
    }
    checkpoints
}

shifted_scores <- function(weights, vector) {
    scores <- vapply(weights, function(row) score(row, vector), 0)
    scores - max(scores)
}
softmax_probabilities <- function(weights, vector) {
    shifted <- shifted_scores(weights, vector)
    total <- ordered_sum(exp(shifted))
    exp(shifted) / total
}
predicted_class <- function(probabilities) which.max(probabilities) - 1L
softmax_loss <- function(weights, vector, label) {
    shifted <- shifted_scores(weights, vector)
    log(ordered_sum(exp(shifted))) - shifted[label + 1L]
}
softmax_average_loss <- function(w, x, labels) ordered_sum(vapply(
    seq_along(x),
    function(i) softmax_loss(w, x[[i]], labels[i]),
    0
)) / length(x)
softmax_objective <- function(
    w,
    x,
    labels,
    lambda
) softmax_average_loss(w, x, labels) + lambda * ordered_sum(unlist(
    lapply(w, function(row) row[-1L] * row[-1L]),
    use.names = FALSE
)) / 2
softmax_gradient <- function(w, x, labels, lambda) {
    totals <- lapply(w, function(row) numeric(length(row)))
    for (i in seq_along(x)) {
        probabilities <- softmax_probabilities(w, x[[i]])
        for (k in seq_along(w)) {
            error <- probabilities[k] - as.numeric(labels[i] == k - 1L)
            for (j in seq_along(w[[k]])) totals[[k]][j] <- totals[[k]][j] + error * x[[i]][j]
        }
    }
    lapply(seq_along(w), function(k) totals[[k]] / length(x) + c(0, lambda * w[[k]][-1L]))
}
softmax_train <- function(x, labels, classes, lambda, rate, iterations) {
    w <- lapply(seq_len(classes), function(k) numeric(length(x[[1L]])))
    checkpoints <- list(list(iteration = 0L, weights = w))
    for (t in seq_len(iterations)) {
        direction <- softmax_gradient(w, x, labels, lambda)
        w <- lapply(seq_along(w), function(k) w[[k]] - rate * direction[[k]])
        if (t %% 100L == 0L) checkpoints <- c(checkpoints, list(list(iteration = t, weights = w)))
    }
    checkpoints
}
